def f(inp):
    g=[r[:] for r in inp]; H=len(g); W=len(g[0])
    # find color c forming closed rectangle? use demo rule: recolor interior cells of the rectangle
    # simpler: find non-background shape: 8s; fill its interior with 4
    # general: interior = cells enclosed by shape; here all cells not adjacent to background within rect.
    from collections import deque
    bg=inp[0][0]
    # flood from outside on non-8 cells
    seen=[[False]*W for _ in range(H)]; q=deque()
    for r in range(H):
        for c in range(W):
            if r==0 or c==0 or r==H-1 or c==W-1:
                if inp[r][c]!=8 and not seen[r][c]: seen[r][c]=True;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and inp[nr][nc]!=8:
                seen[nr][nc]=True;q.append((nr,nc))
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=bg and not seen[r][c]: g[r][c]=4
    return g
